import{_ as a,o as s,c as o,al as r}from"./chunks/framework.7vp1BMOE.js";const h=JSON.parse('{"title":"Sensor Hardware & Setup","description":"","frontmatter":{},"headers":[],"relativePath":"en/sensor/index.md","filePath":"en/sensor/index.md"}'),n={name:"en/sensor/index.md"};function t(i,e,l,d,c,m){return s(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="sensor-hardware-setup" tabindex="-1">Sensor Hardware &amp; Setup <a class="header-anchor" href="#sensor-hardware-setup" aria-label="Permalink to &quot;Sensor Hardware &amp; Setup&quot;">​</a></h1><p>This section describes the mandatory and optional sensors and their setup/configuration.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>PX4-based systems use sensors to estimate vehicle state, which is needed for stabilization and to enable autonomous control. Vehicle state information includes: position/altitude, heading, speed, airspeed, orientation (attitude), rates of rotation in different directions, battery level, and so on.</p><p>PX4 <em>minimally requires</em> a gyroscope, accelerometer, magnetometer (compass), and barometer to measure the above states. Fixed-wing and VTOL-vehicles <em>should</em> also include an airspeed sensor. A GPS or other positioning system is needed to enable all automatic modes, and some manual/assisted modes.</p><p><a href="./../flight_controller/pixhawk_series">Pixhawk Series</a> flight controllers already have the minimum set of sensors (other controller platforms often do too). Additional/external sensors can be attached to the controller — an external GPS and compass are recommended, along with an airspeed sensor for VTOL and Fixed wing vehicles.</p><h2 id="sensor-topics" tabindex="-1">Sensor Topics <a class="header-anchor" href="#sensor-topics" aria-label="Permalink to &quot;Sensor Topics&quot;">​</a></h2><p>Mandatory (included in Pixhawk series FCs):</p><ul><li><a href="./../sensor/accelerometer">Accelerometer</a> — Measures changing acceleration.</li><li><a href="./../sensor/gyroscope">Gyroscope</a> — Measures orientation.</li><li><a href="./../gps_compass/magnetometer">Magnetometer (Compass)</a> — Measures heading/direction. External compass recommended!</li><li><a href="./../sensor/barometer">Barometers</a> — Measures altitude (via air pressure).</li></ul><p>Recommended:</p><ul><li><a href="./../sensor/airspeed">Airspeed Sensors</a> — Measures airspeed. Highly recommended for VTOL and Fixed-wing as they are the only mechanism to detect stall.</li><li><a href="./../gps_compass/">GNSS (GPS)</a> — Measures global position. Needed for missions, and some other automatic and manual/assisted modes.</li><li><a href="./../gps_compass/rtk_gps">RTK GNSS (GPS)</a> — GNSS with centimetre-level accuracy. Some setups also allow heading to be determine from GNSS rather than a magnetometer.</li></ul><p>Optional:</p><ul><li><a href="./../sensor/rangefinders">Distance Sensors (Rangefinders)</a> — Measures distance to target. Aids landing, object avoidance, and terrain following.</li><li><a href="./../sensor/optical_flow">Optical Flow</a> — Estimates velocity using a downward facing camera and a downward facing distance sensor. Enables a more accurate position lock than GPS alone, and can be used indoors when no GPS signal is available.</li><li><a href="./../sensor/tachometers">Tachometers (Revolution Counters)</a> — Only used for logging.</li></ul><p>Primarily for OEMs/Manufacturers:</p><ul><li><a href="./../advanced_config/imu_factory_calibration">IMU/Compass Factory Calibration</a> — Save calibration settings to persistent storage.</li><li><a href="./../advanced_config/sensor_thermal_calibration">Sensor Thermal Compensation</a> — Compensate sensors for temperature variations.</li></ul>',15)])])}const u=a(n,[["render",t]]);export{h as __pageData,u as default};
